	/* @socom-skeleton stub fpsMax$2681 */
	static int fpsMax;
	/* @socom-skeleton stub fpsMin$2684 */
	static int fpsMin;
	/* @socom-skeleton stub fpsCount$2687 */
	static int fpsCount;
	/* @socom-skeleton stub fpsSum$2690 */
	static int fpsSum;
	/* @socom-skeleton stub shadowTime$2751 */
